{
  "root_cause": "The datepicker widget shows the calendar on focus, and the underlying VCP library prevents the default action of the Tab key to manage keyboard navigation within the calendar. However, in this scenario, the Tab keydown event on the departure input was marked as defaultPrevented=true, preventing focus from moving to the next field (passengers input). This occurs because the datepicker's focus-in listener triggers the calendar to show, and the VCP library's internal handling of the Tab key blocks focus escape when the calendar is open.",
  "repair_strategy": "Modify the datepicker widget to not show the calendar on focus. Instead, show it on click and on Enter/Space keydown when the input is focused. This preserves mouse functionality and provides a keyboard alternative to open the datepicker, while allowing the Tab key to function normally for form navigation.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "EventHandler.on(document, EVENT_FOCUSIN_DATA_API, SELECTOR_DATA_TOGGLE, function () {
  // Handle focus for input elements
  if (this.tagName !== 'INPUT') {
    return
  }

  Datepicker.getOrCreateInstance(this).show()
})",
      "after": ""
    },
    {
      "keystrokes": "",
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "EventHandler.on(document, EVENT_CLICK_DATA_API, SELECTOR_DATA_TOGGLE, function (event) {
  // Only handle if not an input (inputs use focus)
  // Skip inline datepickers (they're always visible)
  if (this.tagName === 'INPUT' || this.dataset.bsInline === 'true') {
    return
  }

  event.preventDefault()
  Datepicker.getOrCreateInstance(this).toggle()
})",
      "after": "EventHandler.on(document, EVENT_CLICK_DATA_API, SELECTOR_DATA_TOGGLE, function (event) {
  // Skip inline datepickers (they're always visible)
  if (this.dataset.bsInline === 'true') {
    return
  }

  event.preventDefault()
  Datepicker.getOrCreateInstance(this).toggle()
})"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onInputKeydown: (event: Event) => void | null"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    this._isInput = this._element.tagName === 'INPUT'
    this._isInline = this._config.inline

    // For inline mode, look for a hidden input child to bind to
    if (this._isInline && !this._isInput) {
      this._boundInput = this._element.querySelector<HTMLInputElement>('input[type="hidden"], input[name]')
    }",
      "after": "    this._isInput = this._element.tagName === 'INPUT'
    this._isInline = this._config.inline

    // For inline mode, look for a hidden input child to bind to
    if (this._isInline && !this._isInput) {
      this._boundInput = this._element.querySelector<HTMLInputElement>('input[type="hidden"], input[name]')
    }

    if (this._isInput) {
      this._onInputKeydown = (event) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          this.show()
        }
      }
      EventHandler.on(this._element, 'keydown', this._onInputKeydown)
    }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "  override dispose(): void {
    if (this._themeObserver) {
      this._themeObserver.disconnect()
      this._themeObserver = null
    }

    if (this._onOutside) {
      EventHandler.off(document, EVENT_FOCUSIN, this._onOutside)
      EventHandler.off(document, EVENT_POINTERDOWN, this._onOutside)
    }

    if (this._onInputKeydown) {
      EventHandler.off(this._element, 'keydown', this._onInputKeydown)
      this._onInputKeydown = null
    }

    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can now tab from the departure date input to the passengers input without interference. The datepicker remains operable via mouse click and keyboard (Enter/Space) for users who need to select a date.",
  "functional_risks": [
    "Users who rely on the datepicker opening automatically on focus may need to adjust to using Enter/Space to open it.",
    "Screen reader users might experience a change in behavior when focusing the input, though the alternative keyboard activation should maintain accessibility.",
    "Inline datepickers are unaffected by this change as they are always visible and do not rely on the focus/show behavior."
  ],
  "verification_requirements": [
    "Verify that pressing Tab from the departure date input moves focus to the passengers input.",
    "Verify that pressing Enter or Space on the departure date input opens the datepicker calendar.",
    "Verify that clicking the departure date input opens the datepicker calendar (for mouse users).",
    "Verify that selecting a date in the calendar updates the input value and closes the calendar (in single selection mode).",
    "Verify that the datepicker closes when clicking outside the calendar (outside both input and calendar)."
  ]
}
